  ('INDEX','public','ix_savedsearch_user_case','',NULL,NULL,NULL),
  ('INDEX','public','ix_section_case_order','',NULL,NULL,NULL),
  ('INDEX','public','ix_workspaceview_case_shared','',NULL,NULL,NULL),
